As used in the foregoing definitions and hereinafter halo defines fluoro, chloro, bromo and iodo; Ci.-talkyl as a group or part of a group encompasses the straight and branched chain saturated hydrocarbon radicals having from 1 to 4 carbon atoms such as, for example, methyl, ethyl, propyl, butyl and the like; Cι_6alkyl as a group or part of a • group encompasses the straight and branched chain saturated hydrocarbon radicals as defined in Ci^alkyl as well as the higher homologues thereof containing 5 or 6 carbon atoms such as, for example, pentyl or hexyl; 

 encompasses the straight and branched chain saturated bivalent hydrocarbon radicals having from 1 to 6 carbon atoms such as, for example, methylene, 1,2-ethanediyl, 1,3-propanediyl, 1 ,4-butanediyl, 1,5-pentanediyl, 1,6-hexanediyl, 1,2-propanediyl, 1,2-butanediyl, 2,3-butanediyl and the like; C2-3alkanediyl encompasses the straight and branched chain saturated bivalent hydrocarbon radicals having 2 or 3 carbon atoms such as, for example, 1,2-ethanediyl, 1,2-propanediyl and 1,3-propanediyl. 

For therapeutic use, salts of the compounds of formula (I) are those wherein the counteπon is pharmaceutically acceptable However, salts of acids and bases which are non-pharmaceutically acceptable may also find use, for example, in the preparation or purification of a pharmaceutically acceptable compound. All salts, whether pharmaceutically acceptable or not are included within the ambit of the present invention
